", "t": [["write_file", "{"path":"D:\\Projects\\local_ai\\strata-lab\\runs\\work\\hermes\\jsondiff-1794053379\\jsondiff.py","content":"import json\n\n\ndef diff(a, b):\n    lines = []\n    _walk(a, b, \"$\", lines)\n    return sorted(lines)\n\n\ndef _render(value):\n    return json.dumps(value, sort_keys=True)\n\n\ndef _equal(a, b):\n    return type(a) is type(b) and a == b\n\n\ndef _walk(a, b, path, out):\n    if _equal(a, b):\n        return\n    if isinstance(a, dict) and isinstance(b, dict):\n        for key in a:\n            if key not in b:\n                out.append(\"- {}.{}: {}\".format(path, key, _render(a[key])))\n        for key in b:\n            if key not in a:\n                out.append(\"+ {}.{}: {}\".format(path, key, _render(b[key])))\n        for key in sorted(set(a) & set(b)):\n            _walk(a[key], b[key], \"{}.{}\".format(path, key), out)\n    elif isinstance(a, list) and isinstance(b, list):\n        for i in range(max(len(a), len(b))):\n            child = \"{}[{}]\".format(path, i)\n            if i >= len(b):\n                out.append(\"- {}: {}\".format(child, _render(a[i])))\n            elif i >= len(a):\n                out.append(\"+ {}: {}\".format(child, _render(b[i])))\n            else:\n                _walk(a[i], b[i], child, out)\n    else:\n        out.append(\"~ {}: {} -> {}\".format(path, _render(a), _render(b)))\n"}"]]}

